using FluentAssertions;
using NUnit.Framework;
using NzbDrone.Core.MediaFiles.RecoverableOperations;
using NzbDrone.Core.Test.Framework;
namespace NzbDrone.Core.Test.MediaFiles.RecoverableOperations { [TestFixture] public class RecoverableOperationRecoveryServiceFixture : DbTest<RecoverableOperationRepository, RecoverableOperation> { [Test] public void corrupt_low_state_should_not_starve_later_recoverable_rows() { var corrupt = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("corrupt", "movie:corrupt")); corrupt.State = (RecoverableOperationState)999; Storage.Update(corrupt); var later = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("after-corrupt", "movie:after-corrupt")); var service = new RecoverableOperationRecoveryService(Subject); service.Classify(1).Should().Equal(later.Id); Subject.GetById(corrupt.Id).State.Should().Be((RecoverableOperationState)999); Subject.GetById(later.Id).State.Should().Be(RecoverableOperationState.RecoveryRequired); } [Test] public void repeated_bounded_runs_advance_past_low_unsupported() { var low = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("low", "movie:10")); var later = Subject.CreatePending(RecoverableOperationRepositoryFixture.Request("later", "movie:11")); var service = new RecoverableOperationRecoveryService(Subject); service.Classify(1).Should().Equal(low.Id); Subject.GetById(low.Id).State.Should().Be(RecoverableOperationState.RecoveryRequired); service.Classify(1).Should().Equal(later.Id); Subject.GetById(later.Id).State.Should().Be(RecoverableOperationState.RecoveryRequired); } } }
